module calendar(
    input CLK, RST,
    output reg [5:0] Hours, Mins, Secs
);
    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            Secs <= 0;
            Mins <= 0;
            Hours <= 0;
        end
        else begin
            Secs <= (Secs == 59) ? 0 : Secs + 1;
            Mins <= (Secs == 59) ? (Mins == 59) ? 0 : Mins + 1 : Mins;
            Hours <= (Secs == 59 && Mins == 59) ? (Hours == 23) ? 0 : Hours + 1 : Hours;
        end
    end
endmodule
